package com.brightloop.plan;
import com.brightloop.catalog.ProductRepository;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class PlanService {
 private final PlanRepository plans;private final ProductRepository products;public PlanService(PlanRepository p,ProductRepository pr){plans=p;products=pr;}
 @Transactional(readOnly=true) public java.util.List<PlanDtos.Response> list(){return plans.findAll().stream().map(PlanDtos.Response::of).toList();}
 @Transactional public PlanDtos.Response create(PlanDtos.Request r){validateDates(r);var plan=new Plan(product(r.productId()),r.name(),r.description(),r.billingPrice(),r.billingFrequency(),r.minimumQuantity(),r.availableFrom(),r.availableUntil(),r.autoCloseOnExpiry(),r.allowEarlyClosure(),r.allowPause(),r.allowRenewal(),r.status()==null?"ACTIVE":r.status());return PlanDtos.Response.of(plans.save(plan));}
 @Transactional public PlanDtos.Response update(Long id,PlanDtos.Request r){validateDates(r);var p=plans.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found"));p.changeProduct(product(r.productId()));p.update(r.name(),r.description(),r.billingPrice(),r.billingFrequency(),r.minimumQuantity(),r.availableFrom(),r.availableUntil(),r.autoCloseOnExpiry(),r.allowEarlyClosure(),r.allowPause(),r.allowRenewal(),r.status()==null?"ACTIVE":r.status());return PlanDtos.Response.of(p);}
 @Transactional public void archive(Long id){var p=plans.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found"));p.update(p.getName(),p.getDescription(),p.getBillingPrice(),p.getBillingFrequency(),p.getMinimumQuantity(),p.getAvailableFrom(),p.getAvailableUntil(),p.isAutoCloseOnExpiry(),p.isAllowEarlyClosure(),p.isAllowPause(),p.isAllowRenewal(),"ARCHIVED");}
 private com.brightloop.catalog.Product product(Long id){return products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));}
 private void validateDates(PlanDtos.Request r){if(r.availableFrom()!=null&&r.availableUntil()!=null&&r.availableUntil().isBefore(r.availableFrom()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Plan end date must be after its start date");}
}
